/*** Sphere works ⚙️
A generative construction machine that stamps, grows,
 and packs spheres into an emergent ball field.
***/

let spheres = [];
let machine;
let target;
let buildTimer = 0;

const MAX_SPHERES = 140;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  strokeCap(ROUND);

  machine = new Machine();
  chooseTarget();
}

function draw() {
  background(8, 10, 14);

  drawBlueprintGrid();
  updateSpheres();
  drawSpheres();

  machine.update();
  machine.display();

  buildTimer++;

  if (dist(machine.head.x, machine.head.y, target.x, target.y) < 6 && buildTimer > 22) {
    stampSphere(target.x, target.y);
    chooseTarget();
    buildTimer = 0;
  }
}

function chooseTarget() {
  let margin = 120;

  if (spheres.length === 0) {
    target = createVector(width * 0.5, height * 0.58);
  } else {
    let parent = random(spheres);
    let angle = random(TWO_PI);
    let radius = random(parent.r + 18, parent.r + 95);

    target = createVector(
      constrain(parent.x + cos(angle) * radius, margin, width - margin),
      constrain(parent.y + sin(angle) * radius, margin + 40, height - margin)
    );
  }

  machine.setTarget(target);
}

function stampSphere(x, y) {
  spheres.push({
    x,
    y,
    r: 3,
    targetR: random(16, 52),
    vx: 0,
    vy: 0,
    pressure: 0,
    age: 0,
    hue: random([35, 48, 190, 205, 215])
  });

  if (spheres.length > MAX_SPHERES) {
    spheres.shift();
  }
}

function updateSpheres() {
  for (let s of spheres) {
    s.age++;
    s.pressure *= 0.88;

    if (s.r < s.targetR) {
      s.r += 0.18;
    }
  }

  for (let i = 0; i < spheres.length; i++) {
    let a = spheres[i];

    for (let j = i + 1; j < spheres.length; j++) {
      let b = spheres[j];

      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let d = sqrt(dx * dx + dy * dy);
      let minD = a.r + b.r + 3;

      if (d > 0 && d < minD) {
        let push = (minD - d) * 0.018;

        let nx = dx / d;
        let ny = dy / d;

        a.vx -= nx * push;
        a.vy -= ny * push;
        b.vx += nx * push;
        b.vy += ny * push;

        a.pressure += push * 8;
        b.pressure += push * 8;
      }
    }
  }

  for (let s of spheres) {
    s.vx *= 0.82;
    s.vy *= 0.82;

    s.x += s.vx;
    s.y += s.vy;

    s.x = constrain(s.x, 90 + s.r, width - 90 - s.r);
    s.y = constrain(s.y, 110 + s.r, height - 80 - s.r);
  }
}

function drawSpheres() {
  for (let s of spheres) {
    let glow = constrain(s.pressure, 0, 1);

    noStroke();
    fill(s.hue, 70, 100, 8 + glow * 20);
    circle(s.x, s.y, s.r * 2.7);

    fill(s.hue, 45, 92, 18);
    circle(s.x, s.y, s.r * 2.15);

    stroke(210, 220, 235, 95);
    strokeWeight(1.1);
    fill(s.hue, 35 + glow * 50, 18 + glow * 55, 88);
    circle(s.x, s.y, s.r * 2);

    noStroke();
    fill(220, 30, 100, 45);
    circle(s.x - s.r * 0.32, s.y - s.r * 0.38, s.r * 0.32);
  }
}

class Machine {
  constructor() {
    this.railY = 70;
    this.carriage = createVector(width * 0.5, this.railY);
    this.head = createVector(width * 0.5, height * 0.5);
    this.target = createVector(width * 0.5, height * 0.5);
  }

  setTarget(v) {
    this.target = v.copy();
  }

  update() {
    this.carriage.x = lerp(this.carriage.x, this.target.x, 0.045);
    this.head.x = lerp(this.head.x, this.target.x, 0.055);
    this.head.y = lerp(this.head.y, this.target.y, 0.055);
  }

  display() {
    stroke(210, 220, 230, 95);
    strokeWeight(3);
    line(70, this.railY, width - 70, this.railY);

    stroke(210, 220, 230, 35);
    strokeWeight(1);
    for (let x = 90; x < width - 90; x += 35) {
      line(x, this.railY - 8, x, this.railY + 8);
    }

    noStroke();
    fill(210, 220, 230, 190);
    rectMode(CENTER);
    rect(this.carriage.x, this.railY, 46, 22, 4);

    let mid = createVector(
      lerp(this.carriage.x, this.head.x, 0.48) + sin(frameCount * 0.04) * 24,
      lerp(this.railY, this.head.y, 0.48)
    );

    stroke(235, 240, 245, 145);
    strokeWeight(4);
    line(this.carriage.x, this.railY + 12, mid.x, mid.y);
    line(mid.x, mid.y, this.head.x, this.head.y);

    noStroke();
    fill(240, 245, 250, 220);
    circle(mid.x, mid.y, 9);

    fill(120, 190, 255, 38);
    circle(this.head.x, this.head.y, 34);

    fill(160, 215, 255, 230);
    circle(this.head.x, this.head.y, 9);

    stroke(120, 190, 255, 80);
    strokeWeight(1.5);
    line(this.head.x, this.head.y, target.x, target.y);
  }
}

function drawBlueprintGrid() {
  stroke(255, 255, 255, 8);
  strokeWeight(1);

  for (let x = 0; x < width; x += 40) {
    line(x, 0, x, height);
  }

  for (let y = 0; y < height; y += 40) {
    line(0, y, width, y);
  }

  stroke(120, 190, 255, 18);
  line(0, height * 0.58, width, height * 0.58);
}

function mousePressed() {
  stampSphere((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  machine = new Machine();
  spheres = [];
  chooseTarget();
}

